import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene position
  const pos = config.scenePosition || {};
  group.position.set(pos.x ?? 0, pos.y ?? 0, pos.z ?? 0);

  if (pos.rotationXYZ) {
    group.rotation.order = 'XYZ';
    group.rotation.set(pos.rotationXYZ[0], pos.rotationXYZ[1], pos.rotationXYZ[2]);
  }

  if (pos.scaleXYZ) {
    group.scale.set(pos.scaleXYZ[0], pos.scaleXYZ[1], pos.scaleXYZ[2]);
  }

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load brushed metal texture
  const texture = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');

  // Create material
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide,
  });

  // Create mesh
  const plane = new THREE.Mesh(geometry, material);
  group.add(plane);

  // Render text via fontAtlas
  const textLabel = config.textContent?.label || 'Get started';
  const textMesh = ctx.fontAtlas.createText(textLabel, {
    fontSize: 0.34,
    color: 0xff2a38,
    anchor: 'center',
  });

  if (textMesh) {
    textMesh.position.z = 0.01;
    group.add(textMesh);
  }

  // Track timelines for cleanup
  const timelines = [];

  // Setup cleanup
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  // Setup event handlers
  group.userData.handlers = {};

  return group;
}
